/**
 * The app, in Russian.
 *
 * Keyed on the ENGLISH source string, exactly as the other tables are, because
 * that is what ui() is handed at the call site. One character out and the
 * lookup misses in silence: the app draws the English and nothing anywhere
 * reports a problem.
 *
 * WHO THIS IS FOR. Russian speakers learning German — the largest group of
 * newcomers in Germany that had no interface here. The course they are doing
 * is German; this table is the app around it, so it never explains German
 * grammar, it only says Save, Next, and Your streak ended.
 *
 * ADDRESS. Ты throughout, never вы — matching the German table's du and the
 * English source's plain second person. An app talking to one person who
 * chose to be here, not an official form. Что-то пошло не так, not
 * Произошла ошибка.
 *
 * ё IS WRITTEN. Ещё, всё, твоё. It is optional in Russian print and omitted
 * in most of it, but this is an app read in a hurry on a phone by somebody
 * whose attention is on the German, and все and всё are different words.
 */
